225: plist_err_t plist_from_memory(const char *plist_data, uint32_t length, plist_t *plist, plist_format_t *format)
226: {
227:     plist_err_t res = PLIST_ERR_UNKNOWN;
228:     if (!plist) {
229:         return PLIST_ERR_INVALID_ARG;
230:     }
231:     *plist = NULL;
232:     if (!plist_data || length == 0) {
233:         return PLIST_ERR_INVALID_ARG;
234:     }
235:     plist_format_t fmt = PLIST_FORMAT_NONE;
236:     if (format) *format = PLIST_FORMAT_NONE;
237:     if (plist_is_binary(plist_data, length)) {
238:         res = plist_from_bin(plist_data, length, plist);
239:         fmt = PLIST_FORMAT_BINARY;
240:     } else {
241:         uint32_t pos = 0;
242:         int is_json = 0;
243:         int is_xml = 0;
244:         /* skip whitespace */
245:         SKIP_WS(plist_data, pos, length);
246:         if (pos >= length) {
247:             return PLIST_ERR_PARSE;
248:         }
249:         if (plist_data[pos] == '<' && (length-pos > 3) && !isxdigit(plist_data[pos+1]) && !isxdigit(plist_data[pos+2]) && !isxdigit(plist_data[pos+3])) {
250:             is_xml = 1;
251:         } else if (plist_data[pos] == '[') {
252:             /* only valid for json */
253:             is_json = 1;
254:         } else if (plist_data[pos] == '(') {
255:             /* only valid for openstep */
256:         } else if (plist_data[pos] == '{') {
257:             /* this could be json or openstep */
258:             pos++;
259:             SKIP_WS(plist_data, pos, length);
260:             if (pos >= length) {
261:                 return PLIST_ERR_PARSE;
262:             }
263:             if (plist_data[pos] == '"') {
264:                 /* still could be both */
265:                 pos++;
266:                 while (pos < length) {
267:                     FIND_NEXT(plist_data, pos, length, '"');
268:                     if (plist_data[pos-1] != '\\') {
269:                         break;
270:                     }
271:                     pos++;
272:                 }
273:                 if (pos >= length) {
274:                     return PLIST_ERR_PARSE;
275:                 }
276:                 if (plist_data[pos] == '"') {
277:                     pos++;
278:                     SKIP_WS(plist_data, pos, length);
279:                     if (pos >= length) {
280:                         return PLIST_ERR_PARSE;
281:                     }
282:                     if (plist_data[pos] == ':') {
283:                         /* this is definitely json */
284:                         is_json = 1;
285:                     }
286:                 }
287:             }
288:         }
289:         if (is_xml) {
290:             res = plist_from_xml(plist_data, length, plist);
291:             fmt = PLIST_FORMAT_XML;
292:         } else if (is_json) {
293:             res = plist_from_json(plist_data, length, plist);
294:             fmt = PLIST_FORMAT_JSON;
295:         } else {
296:             res = plist_from_openstep(plist_data, length, plist);
297:             fmt = PLIST_FORMAT_OSTEP;
298:         }
299:     }
300:     if (format && res == PLIST_ERR_SUCCESS) {
301:         *format = fmt;
302:     }
303:     return res;
304: }
