306: plist_err_t plist_read_from_file(const char *filename, plist_t *plist, plist_format_t *format)
307: {
308:     if (!filename || !plist) {
309:         return PLIST_ERR_INVALID_ARG;
310:     }
311:     FILE *f = fopen(filename, "rb");
312:     if (!f) {
313:         return PLIST_ERR_IO;
314:     }
315:     struct stat fst;
316:     fstat(fileno(f), &fst);
317:     if ((uint64_t)fst.st_size > UINT32_MAX) {
318:         return PLIST_ERR_NO_MEM;
319:     }
320:     uint32_t total = (uint32_t)fst.st_size;
321:     if (total == 0) {
322:         return PLIST_ERR_PARSE;
323:     }
324:     char *buf = (char*)malloc(total);
325:     if (!buf) {
326:         fclose(f);
327:         return PLIST_ERR_NO_MEM;
328:     }
329:     uint32_t done = 0;
330:     while (done < total) {
331:         ssize_t r = fread(buf + done, 1, total - done, f);
332:         if (r <= 0) {
333:             break;
334:         }
335:         done += r;
336:     }
337:     fclose(f);
338:     if (done < total) {
339:         free(buf);
340:         return PLIST_ERR_IO;
341:     }
342:     plist_err_t res = plist_from_memory(buf, total, plist, format);
343:     free(buf);
344:     return res;
345: }
