364: static unsigned int dict_key_hash(const void *data)
365: {
366:     plist_data_t keydata = (plist_data_t)data;
367:     unsigned int hash = 5381;
368:     size_t i;
369:     char *str = keydata->strval;
370:     for (i = 0; i < keydata->length; str++, i++) {
371:         hash = ((hash << 5) + hash) + *str;
372:     }
373:     return hash;
374: }
375: 
376: static int dict_key_compare(const void* a, const void* b)
377: {
378:     plist_data_t data_a = (plist_data_t)a;
379:     plist_data_t data_b = (plist_data_t)b;
380:     if (data_a->strval == NULL || data_b->strval == NULL) {
381:         return FALSE;
382:     }
383:     if (data_a->length != data_b->length) {
384:         return FALSE;
385:     }
386:     return (strcmp(data_a->strval, data_b->strval) == 0) ? TRUE : FALSE;
387: }
