389: static void _plist_free_data(plist_data_t data)
390: {
391:     if (!data) return;
392:     switch (data->type) {
393:         case PLIST_KEY:
394:         case PLIST_STRING:
395:             free(data->strval);
396:             data->strval = NULL;
397:             break;
398:         case PLIST_DATA:
399:             free(data->buff);
400:             data->buff = NULL;
401:             break;
402:         case PLIST_ARRAY:
403:             ptr_array_free((ptrarray_t*)data->hashtable);
404:             data->hashtable = NULL;
405:             break;
406:         case PLIST_DICT: {
407:             hashtable_t *ht = (hashtable_t*)data->hashtable;
408:             // PLIST_DICT hashtables must not own/free values; values are freed via node tree.
409:             assert(!ht || ht->free_func == NULL);
410:             if (ht) ht->free_func = NULL;
411:             hash_table_destroy(ht);
412:             data->hashtable = NULL;
413:             break;
414:         }
415:         default:
416:             break;
417:     }
418: }
