427: static int plist_free_children(node_t root)
428: {
429:     if (!root) return NODE_ERR_INVALID_ARG;
430: 
431:     if (!node_first_child(root)) {
432:         return NODE_ERR_SUCCESS;
433:     }
434: 
435:     size_t cap = 64, sp = 0;
436:     node_t *stack = (node_t*)malloc(cap * sizeof(*stack));
437:     if (!stack) return NODE_ERR_NO_MEM;
438: 
439:     // Push *direct* children onto the stack, detached from root.
440:     for (;;) {
441:         node_t ch = node_first_child(root);
442:         if (!ch) break;
443: 
444:         int di = node_detach(root, ch);
445:         if (di < 0) {
446:             free(stack);
447:             return di;
448:         }
449: 
450:         if (sp == cap) {
451:             cap += 64;
452:             node_t *tmp = (node_t*)realloc(stack, cap * sizeof(*stack));
453:             if (!tmp) {
454:                 free(stack);
455:                 return NODE_ERR_NO_MEM;
456:             }
457:             stack = tmp;
458:         }
459:         stack[sp++] = ch;
460:     }
461: 
462:     // Now free the detached subtree nodes (and their descendants).
463:     while (sp) {
464:         node_t node = stack[sp - 1];
465:         node_t ch = node_first_child(node);
466:         if (ch) {
467:             int di = node_detach(node, ch);
468:             if (di < 0) {
469:                 free(stack);
470:                 return di;
471:             }
472: 
473:             if (sp == cap) {
474:                 cap += 64;
475:                 node_t *tmp = (node_t*)realloc(stack, cap * sizeof(*stack));
476:                 if (!tmp) {
477:                     free(stack);
478:                     return NODE_ERR_NO_MEM;
479:                 }
480:                 stack = tmp;
481:             }
482:             stack[sp++] = ch;
483:             continue;
484:         }
485: 
486:         plist_data_t data = plist_get_data(node);
487:         plist_free_data(data);
488:         node->data = NULL;
489: 
490:         node_destroy(node);
491: 
492:         sp--;
493:     }
494: 
495:     free(stack);
496:     return NODE_ERR_SUCCESS;
497: }
498: 
499: static int plist_free_node(node_t root)
500: {
501:     if (!root) return NODE_ERR_INVALID_ARG;
502: 
503:     int root_index = -1;
504: 
505:     if (root->parent) {
506:         root_index = node_detach(root->parent, root);
507:         if (root_index < 0) {
508:             return root_index;
509:         }
510:     }
511: 
512:     int r = plist_free_children(root);
513:     if (r < 0) {
514:         // root is already detached; caller should treat as error.
515:         return r;
516:     }
517: 
518:     plist_data_t data = plist_get_data(root);
519:     plist_free_data(data);
520:     root->data = NULL;
521: 
522:     node_destroy(root);
523: 
524:     return root_index;
525: }
