728: static int plist_copy_node_shallow(node_t node, plist_t *out_newnode, plist_data_t *out_newdata, plist_type *out_type)
729: {
730:     if (!node || !out_newnode || !out_newdata || !out_type) return NODE_ERR_INVALID_ARG;
731: 
732:     plist_data_t data = plist_get_data(node);
733:     if (!data) return NODE_ERR_INVALID_ARG;
734: 
735:     plist_data_t newdata = plist_new_plist_data();
736:     if (!newdata) return NODE_ERR_NO_MEM;
737: 
738:     memcpy(newdata, data, sizeof(struct plist_data_s));
739: 
740:     plist_type node_type = plist_get_node_type(node);
741:     switch (node_type) {
742:         case PLIST_DATA:
743:             if (data->buff) {
744:                 newdata->buff = (uint8_t*)malloc(data->length);
745:                 if (!newdata->buff) {
746:                     plist_free_data(newdata);
747:                     return NODE_ERR_NO_MEM;
748:                 }
749:                 memcpy(newdata->buff, data->buff, data->length);
750:             } else {
751:                 newdata->buff = NULL;
752:                 newdata->length = 0;
753:             }
754:             break;
755: 
756:         case PLIST_KEY:
757:         case PLIST_STRING:
758:             if (data->strval) {
759:                 size_t n = strlen(data->strval);
760:                 newdata->strval = (char*)malloc(n+1);
761:                 if (!newdata->strval) {
762:                     plist_free_data(newdata);
763:                     return NODE_ERR_NO_MEM;
764:                 }
765:                 memcpy(newdata->strval, data->strval, n+1);
766:                 newdata->length = (uint64_t)n;
767:             } else {
768:                 newdata->strval = NULL;
769:                 newdata->length = 0;
770:             }
771:             break;
772: 
773:         case PLIST_ARRAY:
774:             if (data->hashtable) {
775:                 ptrarray_t* pa = ptr_array_new(((ptrarray_t*)data->hashtable)->capacity);
776:                 if (!pa) {
777:                     plist_free_data(newdata);
778:                     return NODE_ERR_NO_MEM;
779:                 }
780:                 newdata->hashtable = pa;
781:             }
782:             break;
783: 
784:         case PLIST_DICT:
785:             if (data->hashtable) {
786:                 hashtable_t* ht = hash_table_new(dict_key_hash, dict_key_compare, NULL);
787:                 if (!ht) {
788:                     plist_free_data(newdata);
789:                     return NODE_ERR_NO_MEM;
790:                 }
791:                 newdata->hashtable = ht;
792:             }
793:             break;
794: 
795:         default:
796:             break;
797:     }
798: 
799:     plist_t newnode = plist_new_node(newdata);
800:     if (!newnode) {
801:         plist_free_data(newdata);
802:         return NODE_ERR_NO_MEM;
803:     }
804: 
805:     *out_newnode = newnode;
806:     *out_newdata = newdata;
807:     *out_type = node_type;
808:     return NODE_ERR_SUCCESS;
809: }
