811: static plist_t plist_copy_node(node_t root)
812: {
813:     typedef struct copy_frame {
814:         node_t       orig;        // original node
815:         plist_t      copy;        // copied node
816:         plist_data_t copydata;    // copied node's data (for cache updates)
817:         plist_type   type;        // copied node type
818:         node_t       next_child;  // next child of orig to process
819:         unsigned int node_index;  // child index (for dict key/value odd/even)
820:         int          depth;       // optional depth tracking
821:     } copy_frame_t;
822: 
823:     if (!root) return NULL;
824: 
825:     // shallow-copy root first
826:     plist_t newroot = NULL;
827:     plist_data_t newroot_data = NULL;
828:     plist_type newroot_type = PLIST_NONE;
829: 
830:     int r = plist_copy_node_shallow(root, &newroot, &newroot_data, &newroot_type);
831:     if (r != NODE_ERR_SUCCESS) {
832:         PLIST_ERR("%s: shallow node copy failed (%d)\n", __func__, r);
833:         return NULL;
834:     }
835: 
836:     // stack of frames
837:     size_t cap = 64, sp = 0;
838:     copy_frame_t *st = (copy_frame_t*)malloc(cap * sizeof(*st));
839:     if (!st) {
840:         plist_free_node((node_t)newroot);
841:         return NULL;
842:     }
843: 
844:     copy_frame_t cf;
845:     cf.orig = root;
846:     cf.copy = newroot;
847:     cf.copydata = newroot_data;
848:     cf.type = newroot_type;
849:     cf.next_child = node_first_child(root);
850:     cf.node_index = 0;
851:     cf.depth = 0;
852:     st[sp++] = cf;
853: 
854:     while (sp) {
855:         copy_frame_t *f = &st[sp - 1];
856: 
857:         if (f->depth > NODE_MAX_DEPTH) {
858:             plist_free_node((node_t)newroot);
859:             free(st);
860:             PLIST_ERR("%s: maximum nesting depth exceeded\n", __func__);
861:             return NULL;
862:         }
863: 
864:         // done with this node?
865:         if (!f->next_child) {
866:             sp--;
867:             continue;
868:         }
869: 
870:         // take next child and advance iterator
871:         node_t ch = f->next_child;
872:         f->next_child = node_next_sibling(ch);
873: 
874:         // shallow copy child
875:         plist_t newch = NULL;
876:         plist_data_t newch_data = NULL;
877:         plist_type newch_type = PLIST_NONE;
878: 
879:         r = plist_copy_node_shallow(ch, &newch, &newch_data, &newch_type);
880:         if (r != NODE_ERR_SUCCESS) {
881:             plist_free_node((node_t)newroot);
882:             free(st);
883:             PLIST_ERR("%s: shallow node copy failed (%d)\n", __func__, r);
884:             return NULL;
885:         }
886: 
887:         // attach child to copied parent
888:         r = node_attach((node_t)f->copy, (node_t)newch);
889:         if (r != NODE_ERR_SUCCESS) {
890:             plist_free_node((node_t)newch);
891:             plist_free_node((node_t)newroot);
892:             free(st);
893:             PLIST_ERR("%s: failed to attach child to copied parent (%d)\n", __func__, r);
894:             return NULL;
895:         }
896: 
897:         // update lookup cache on the *parent* copy
898:         switch (f->type) {
899:             case PLIST_ARRAY:
900:                 if (f->copydata->hashtable) {
901:                     ptr_array_add((ptrarray_t*)f->copydata->hashtable, newch);
902:                 }
903:                 break;
904: 
905:             case PLIST_DICT:
906:                 if (f->copydata->hashtable && (f->node_index % 2 != 0)) {
907:                     node_t new_key = node_prev_sibling((node_t)newch);
908:                     if (new_key) {
909:                         hash_table_insert((hashtable_t*)f->copydata->hashtable, new_key->data, newch);
910:                     }
911:                 }
912:                 break;
913: 
914:             default:
915:                 break;
916:         }
917: 
918:         f->node_index++;
919: 
920:         // push child frame to process its children
921:         if (sp == cap) {
922:             cap += 64;
923:             copy_frame_t *tmp = (copy_frame_t*)realloc(st, cap * sizeof(*st));
924:             if (!tmp) {
925:                 plist_free_node((node_t)newroot);
926:                 free(st);
927:                 PLIST_ERR("%s: out of memory when reallocating\n", __func__);
928:                 return NULL;
929:             }
930:             st = tmp;
931:         }
932: 
933:         copy_frame_t nf;
934:         nf.orig = ch;
935:         nf.copy = newch;
936:         nf.copydata = newch_data;
937:         nf.type = newch_type;
938:         nf.next_child = node_first_child(ch);
939:         nf.node_index = 0;
940:         nf.depth = f->depth + 1;
941:         st[sp++] = nf;
942:     }
943: 
944:     free(st);
945:     return newroot;
946: }
