985: static void _plist_array_post_insert(plist_t node, plist_t item, long n)
986: {
987:     ptrarray_t *pa = (ptrarray_t*)((plist_data_t)((node_t)node)->data)->hashtable;
988:     if (pa) {
989:         /* store pointer to item in array */
990:         ptr_array_insert(pa, item, n);
991:         return;
992:     }
993: 
994:     if (((node_t)node)->count > 100) {
995:        /* make new lookup array */
996:        pa = ptr_array_new(128);
997:        plist_t current = NULL;
998:        for (current = (plist_t)node_first_child((node_t)node);
999:             pa && current;
1000:             current = (plist_t)node_next_sibling((node_t)current))
1001:        {
1002:            ptr_array_add(pa, current);
1003:        }
1004:        ((plist_data_t)((node_t)node)->data)->hashtable = pa;
1005:     }
1006: }
