1008: static void _plist_array_post_set(plist_t node, plist_t item, long n)
1009: {
1010:     ptrarray_t *pa = (ptrarray_t*)((plist_data_t)((node_t)node)->data)->hashtable;
1011: 
1012:     if (pa) {
1013:         if (n < 0 || n >= pa->len) {
1014:            PLIST_ERR("%s: cache index out of range (n=%ld len=%ld)\n", __func__, n, pa->len);
1015:            return;
1016:         }
1017:         ptr_array_set(pa, item, n);
1018:         return;
1019:     }
1020: 
1021:     if (((node_t)node)->count > 100) {
1022:         pa = ptr_array_new(128);
1023:         plist_t current = NULL;
1024:         for (current = (plist_t)node_first_child((node_t)node);
1025:              pa && current;
1026:              current = (plist_t)node_next_sibling((node_t)current))
1027:         {
1028:             ptr_array_add(pa, current);
1029:         }
1030:         ((plist_data_t)((node_t)node)->data)->hashtable = pa;
1031: 
1032:         // Now that it exists (and is filled), apply the set (will no-op if out of range)
1033:         if (pa) {
1034:             ptr_array_set(pa, item, n);
1035:         }
1036:     }
1037: }
