1039: plist_err_t plist_array_set_item(plist_t node, plist_t item, uint32_t n)
1040: {
1041:     if (!PLIST_IS_ARRAY(node) || !item || n >= INT_MAX) {
1042:         PLIST_ERR("invalid argument passed to %s (node=%p, item=%p, n=%u)\n", __func__, node, item, n);
1043:         return PLIST_ERR_INVALID_ARG;
1044:     }
1045:     node_t it = (node_t)item;
1046:     if (it->parent != NULL) {
1047:         assert(it->parent == NULL && "item already has a parent; use plist_copy() or detach first");
1048:         PLIST_ERR("%s: item already has a parent; use plist_copy() or detach first\n", __func__);
1049:         return PLIST_ERR_INVALID_ARG;
1050:     }
1051:     plist_t old_item = plist_array_get_item(node, n);
1052:     if (!old_item) return PLIST_ERR_INVALID_ARG;
1053: 
1054:     int idx = node_detach((node_t)node, (node_t)old_item);
1055:     if (idx < 0) {
1056:         PLIST_ERR("%s: Failed to detach old item (err=%d)\n", __func__, idx);
1057:         return PLIST_ERR_UNKNOWN;
1058:     }
1059: 
1060:     int r = node_insert((node_t)node, (unsigned)idx, (node_t)item);
1061:     if (r != NODE_ERR_SUCCESS) {
1062:         int rb = node_insert((node_t)node, (unsigned)idx, (node_t)old_item);
1063:         if (rb == NODE_ERR_SUCCESS) {
1064:             _plist_array_post_set(node, old_item, idx); // restore cache correctly
1065:             PLIST_ERR("%s: failed to insert replacement (idx=%d err=%d); rollback succeeded\n", __func__, idx, r);
1066:             return (r == NODE_ERR_NO_MEM) ? PLIST_ERR_NO_MEM : PLIST_ERR_UNKNOWN;
1067:         } else {
1068:             PLIST_ERR("%s: insert failed (err=%d) and rollback failed (err=%d); array now missing element at idx=%d\n", __func__, r, rb, idx);
1069:             return PLIST_ERR_UNKNOWN;
1070:         }
1071:     }
1072: 
1073:     _plist_array_post_set(node, item, idx); // update cache
1074:     plist_free_node((node_t)old_item);
1075: 
1076:     return PLIST_ERR_SUCCESS;
1077: }
