1280: plist_t plist_dict_get_item(plist_t node, const char* key)
1281: {
1282:     plist_t ret = NULL;
1283:     if (!PLIST_IS_DICT(node) || !key) {
1284:         PLIST_ERR("invalid argument passed to %s (node=%p, key=%p)\n", __func__, node, key);
1285:         return NULL;
1286:     }
1287:     plist_data_t data = plist_get_data(node);
1288:     if (!data) {
1289:         PLIST_ERR("%s: invalid node\n", __func__);
1290:         return NULL;
1291:     }
1292:     size_t keylen = strlen(key);
1293:     hashtable_t *ht = (hashtable_t*)data->hashtable;
1294:     if (ht) {
1295:         struct plist_data_s sdata = { 0 };
1296:         sdata.strval = (char*)key;
1297:         sdata.length = keylen;
1298:         return (plist_t)hash_table_lookup(ht, &sdata);
1299:     } else {
1300:         plist_t k = NULL;
1301:         for (k = (plist_t)node_first_child((node_t)node); k; ) {
1302:             plist_t v = (plist_t)node_next_sibling(k);
1303:             if (!v) break;
1304:             data = plist_get_data(k);
1305:             assert(PLIST_IS_KEY(k));
1306:             if (!PLIST_IS_KEY(k) || !data || !data->strval) {
1307:                 PLIST_ERR("invalid key node at %p\n", k);
1308:                 break;
1309:             }
1310:             if (data->length == keylen && !memcmp(key, data->strval, keylen+1)) {
1311:                 ret = v;
1312:                 break;
1313:             }
1314:             k = node_next_sibling(v);
1315:         }
1316:     }
1317:     return ret;
1318: }
