1320: plist_err_t plist_dict_set_item(plist_t node, const char* key, plist_t item)
1321: {
1322:     if (!PLIST_IS_DICT(node) || !key || !item) {
1323:         PLIST_ERR("invalid argument passed to %s (node=%p, key=%p, item=%p)\n", __func__, node, key, item);
1324:         return PLIST_ERR_INVALID_ARG;
1325:     }
1326:     node_t it = (node_t)item;
1327:     if (it->parent != NULL) {
1328:         assert(it->parent == NULL && "item already has a parent");
1329:         PLIST_ERR("%s: item already has a parent\n", __func__);
1330:         return PLIST_ERR_INVALID_ARG;
1331:     }
1332: 
1333:     hashtable_t *ht = (hashtable_t*)((plist_data_t)((node_t)node)->data)->hashtable;
1334: 
1335:     plist_t old_item = plist_dict_get_item(node, key);
1336:     plist_t key_node = NULL;
1337: 
1338:     if (old_item) {
1339:         // --- REPLACE EXISTING VALUE ---
1340:         node_t old_val = (node_t)old_item;
1341:         node_t old_key = node_prev_sibling(old_val);
1342:         if (!old_key) {
1343:             PLIST_ERR("%s: corrupt dict (value without key)\n", __func__);
1344:             return PLIST_ERR_UNKNOWN;
1345:         }
1346:         if (!PLIST_IS_KEY((plist_t)old_key)) {
1347:             PLIST_ERR("%s: corrupt dict ('key' node is not PLIST_KEY\n", __func__);
1348:             return PLIST_ERR_UNKNOWN;
1349:         }
1350: 
1351:         // detach old value (do NOT free yet)
1352:         int idx = node_detach((node_t)node, old_val);
1353:         if (idx < 0) {
1354:             PLIST_ERR("%s: failed to detach old value (err=%d)\n", __func__, idx);
1355:             return PLIST_ERR_UNKNOWN;
1356:         }
1357: 
1358:         // insert new value at same position
1359:         int r = node_insert((node_t)node, (unsigned)idx, (node_t)item);
1360:         if (r != NODE_ERR_SUCCESS) {
1361:             // rollback: reinsert old value
1362:             int rb = node_insert((node_t)node, (unsigned)idx, old_val);
1363:             if (rb == NODE_ERR_SUCCESS && ht) {
1364:                 hash_table_insert(ht, ((node_t)old_key)->data, old_item);
1365:             }
1366:             PLIST_ERR("%s: failed to replace dict value (err=%d)\n", __func__, r);
1367:             return PLIST_ERR_UNKNOWN;
1368:         }
1369:         key_node = old_key;
1370: 
1371:         // update hash table
1372:         if (ht) {
1373:             hash_table_insert(ht, (plist_data_t)((node_t)key_node)->data, item);
1374:         }
1375: 
1376:         // now it’s safe to free old value
1377:         plist_free_node(old_val);
1378:     } else {
1379:         // --- INSERT NEW KEY/VALUE PAIR ---
1380:         key_node = plist_new_key(key);
1381:         if (!key_node) return PLIST_ERR_NO_MEM;
1382: 
1383:         int r = node_attach((node_t)node, (node_t)key_node);
1384:         if (r != NODE_ERR_SUCCESS) {
1385:             plist_free_node((node_t)key_node);
1386:             PLIST_ERR("%s: failed to attach dict key (err=%d)\n", __func__, r);
1387:             return PLIST_ERR_UNKNOWN;
1388:         }
1389:         r = node_attach((node_t)node, (node_t)item);
1390:         if (r != NODE_ERR_SUCCESS) {
1391:             // rollback key insertion
1392:             node_detach((node_t)node, (node_t)key_node);
1393:             plist_free_node((node_t)key_node);
1394:             PLIST_ERR("%s: failed to attach dict value (err=%d)\n", __func__, r);
1395:             return PLIST_ERR_UNKNOWN;
1396:         }
1397: 
1398:         if (ht) {
1399:             // store pointer to item in hash table
1400:             hash_table_insert(ht, (plist_data_t)((node_t)key_node)->data, item);
1401:         } else if (((node_t)node)->count > 500) {
1402:             // make new hash table
1403:             ht = hash_table_new(dict_key_hash, dict_key_compare, NULL);
1404:             // calculate the hashes for all entries we have so far
1405:             plist_t current = NULL;
1406:             for (current = (plist_t)node_first_child((node_t)node);
1407:                  ht && current;
1408:                  current = (plist_t)node_next_sibling(node_next_sibling((node_t)current)))
1409:             {
1410:                 hash_table_insert(ht, ((node_t)current)->data, node_next_sibling((node_t)current));
1411:             }
1412:             ((plist_data_t)((node_t)node)->data)->hashtable = ht;
1413:         }
1414:     }
1415:     return PLIST_ERR_SUCCESS;
1416: }
