1442: plist_err_t plist_dict_merge(plist_t *target, plist_t source)
1443: {
1444: 	if (!target || !PLIST_IS_DICT(*target) || !PLIST_IS_DICT(source))
1445: 		return PLIST_ERR_INVALID_ARG;
1446: 
1447: 	char* key = NULL;
1448: 	plist_dict_iter it = NULL;
1449: 	plist_t subnode = NULL;
1450: 	plist_dict_new_iter(source, &it);
1451: 	if (!it)
1452: 		return PLIST_ERR_NO_MEM;
1453: 
1454: 	do {
1455: 		plist_dict_next_item(source, it, &key, &subnode);
1456: 		if (!key)
1457: 			break;
1458: 
1459: 		plist_dict_set_item(*target, key, plist_copy(subnode));
1460: 		free(key);
1461: 		key = NULL;
1462: 	} while (1);
1463: 	free(it);
1464: 	return PLIST_ERR_SUCCESS;
1465: }
