1467: uint8_t plist_dict_get_bool(plist_t dict, const char *key)
1468: {
1469: 	uint8_t bval = 0;
1470: 	uint64_t uintval = 0;
1471: 	const char *strval = NULL;
1472: 	uint64_t strsz = 0;
1473: 	plist_t node = plist_dict_get_item(dict, key);
1474: 	if (!node) {
1475: 		return 0;
1476: 	}
1477: 	switch (plist_get_node_type(node)) {
1478: 	case PLIST_BOOLEAN:
1479: 		plist_get_bool_val(node, &bval);
1480: 		break;
1481: 	case PLIST_INT:
1482: 		plist_get_uint_val(node, &uintval);
1483: 		bval = (uintval) ? 1 : 0;
1484: 		break;
1485: 	case PLIST_STRING:
1486: 		strval = plist_get_string_ptr(node, NULL);
1487: 		if (strval) {
1488: 			if (strcmp(strval, "true")) {
1489: 				bval = 1;
1490: 			} else if (strcmp(strval, "false")) {
1491: 				bval = 0;
1492: 			} else {
1493: 				PLIST_ERR("%s: invalid string '%s' for string to boolean conversion\n", __func__, strval);
1494: 			}
1495: 		}
1496: 		break;
1497: 	case PLIST_DATA:
1498: 		strval = (const char*)plist_get_data_ptr(node, &strsz);
1499: 		if (strval) {
1500: 			if (strsz == 1) {
1501: 				bval = (strval[0]) ? 1 : 0;
1502: 			} else {
1503: 				PLIST_ERR("%s: invalid size %" PRIu64 " for data to boolean conversion\n", __func__, strsz);
1504: 			}
1505: 		}
1506: 		break;
1507: 	default:
1508: 		break;
1509: 	}
1510: 	return bval;
1511: }
