1513: int64_t plist_dict_get_int(plist_t dict, const char *key)
1514: {
1515: 	int64_t intval = 0;
1516: 	const char *strval = NULL;
1517: 	uint64_t strsz = 0;
1518: 	plist_t node = plist_dict_get_item(dict, key);
1519: 	if (!node) {
1520: 		return intval;
1521: 	}
1522: 	switch (plist_get_node_type(node)) {
1523: 	case PLIST_INT:
1524: 		plist_get_int_val(node, &intval);
1525: 		break;
1526: 	case PLIST_STRING:
1527: 		strval = plist_get_string_ptr(node, NULL);
1528: 		if (strval) {
1529: 			intval = strtoll(strval, NULL, 0);
1530: 		}
1531: 		break;
1532: 	case PLIST_DATA:
1533: 		strval = (const char*)plist_get_data_ptr(node, &strsz);
1534: 		if (strval) {
1535: 			if (strsz == 8) {
1536: 				intval = le64toh(*(int64_t*)strval);
